typedef enum { EMPTY, INSTANTIATED, INITIALIZING, STEP_MODE, TERMINATED } Phase;

static int usable(fmi2Status status) {
    return status == fmi2OK || status == fmi2Warning;
}

int run_cs(fmi2String instanceName, fmi2String guid,
           fmi2String resourceLocation,
           const fmi2CallbackFunctions *callbacks,
           fmi2Real startTime, fmi2Real stopTime, fmi2Real stepSize) {
    fmi2Component component;
    fmi2Real time = startTime;
    Phase phase = EMPTY;

    if (stepSize <= 0.0 || stopTime < startTime) return 0;

    component = fmi2Instantiate(instanceName, fmi2CoSimulation, guid,
                                resourceLocation, callbacks,
                                fmi2False, fmi2False);
    if (component == NULL) return 0;
    phase = INSTANTIATED;

    if (!usable(fmi2SetupExperiment(component, fmi2False, 0.0,
                                    startTime, fmi2True, stopTime))) goto fail;
    if (!usable(fmi2EnterInitializationMode(component))) goto fail;
    phase = INITIALIZING;
    if (!usable(fmi2ExitInitializationMode(component))) goto fail;
    phase = STEP_MODE;

    while (time < stopTime) {
        fmi2Real step = stepSize;
        if (time + step > stopTime) step = stopTime - time;
        if (!usable(fmi2DoStep(component, time, step, fmi2False))) goto fail;
        time += step;
    }

    if (!usable(fmi2Terminate(component))) goto fail;
    phase = TERMINATED;
    fmi2FreeInstance(component);
    return phase == TERMINATED;

fail:
    if (phase == STEP_MODE) (void)fmi2Terminate(component);
    fmi2FreeInstance(component);
    return 0;
}
